def count_positive(values):
    i = 0
    count = 0
    while i < len(values):
        if values[i] > 0:
            count += 1
        i += 1
    return count

print(count_positive([3, 0, 2]))
print(count_positive([]))

def last_index(values, target):
    i = 0
    found = -1
    while i < len(values):
        if values[i] == target:
            found = i
        i += 1
    return found

print(last_index([7, 2, 7], 7))
print(last_index([], 7))
